(() => {
'use strict';
const $=id=>document.getElementById(id), W=9,H=11,KEY='beyond-chapel-v1';
const INTRO='Дождь стихает у порога часовни. За дубовой дверью слышен скрежет. «Колокол исчез, но кто-то всё ещё служит здесь», — шепчет Мира. Найдите реликвию и вернитесь к южному входу.';
let state,selected=null,path=[],diceTimer,focus={x:2,y:8};
function random(n){const a=new Uint32Array(1),limit=4294967296-4294967296%n;do{crypto.getRandomValues(a)}while(a[0]>=limit);return a[0]%n+1}
function fresh(){return {version:1,hero:{id:'hero',name:'Эльдар',x:2,y:8,hp:24,max:24,kind:'ranger'},allies:[{id:'mira',name:'Мира',x:1,y:9,hp:18,max:18,kind:'mage'},{id:'bor',name:'Бор',x:3,y:9,hp:28,max:28,kind:'guard'}],enemies:[{id:'e1',name:'Страж',x:6,y:2,hp:13,max:13,kind:'enemy'},{id:'e2',name:'Костяной дозорный',x:7,y:4,hp:11,max:11,kind:'enemy'}],door:false,noise:false,chest:false,relic:false,complete:false,defeated:false,combat:false,round:1,move:5,acted:false,potions:2,gold:0,xp:0,level:1,logs:[INTRO],narrative:INTRO,draft:'',seed:random(99999)}}
try{const saved=JSON.parse(localStorage.getItem(KEY));state=saved&&saved.version===1&&saved.hero&&Array.isArray(saved.logs)?saved:fresh()}catch{state=fresh()}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));$('save-status').textContent='✓ На этом устройстве'}catch{$('save-status').textContent='Сохранение недоступно'}}
function tell(text){state.narrative=text;state.logs.push(text);if(state.logs.length>120)state.logs.shift()}
function wall(x,y){return x<=0||x>=8||y<=0||y>=10||(y===5&&x!==4)||(x===3&&y===3)||(x===6&&y===7)}
function object(x,y){if(x===4&&y===5&&!state.door)return'door';if(x===2&&y===2&&!state.chest)return'chest';if(x===6&&y===1&&!state.relic)return'altar';if(x===4&&y===9)return'exit';return null}
function entities(){return [state.hero,...state.allies,...state.enemies].filter(e=>e.hp>0)}
function occupant(x,y){return entities().find(e=>e.x===x&&e.y===y)}
function blocked(x,y){return wall(x,y)||['door','chest','altar'].includes(object(x,y))}
function dist(a,b){return Math.abs(a.x-b.x)+Math.abs(a.y-b.y)}
function visible(x,y){return state.door||y>=5}
function route(start,target,occupied=true){const mover=occupant(start.x,start.y);const q=[[start]],seen=new Set([start.x+','+start.y]);while(q.length){const p=q.shift(),v=p[p.length-1];if(v.x===target.x&&v.y===target.y)return p.slice(1);for(const [dx,dy]of[[0,-1],[1,0],[0,1],[-1,0]]){const n={x:v.x+dx,y:v.y+dy},k=n.x+','+n.y;const other=occupant(n.x,n.y);const occupiedBlock=occupied&&other&&((n.x===target.x&&n.y===target.y)||((other.kind==='enemy')!==(mover?.kind==='enemy')));if(seen.has(k)||blocked(n.x,n.y)||occupiedBlock)continue;seen.add(k);q.push([...p,n])}}return null}
function line(a,b){let x=a.x,y=a.y,dx=Math.abs(b.x-x),sx=x<b.x?1:-1,dy=-Math.abs(b.y-y),sy=y<b.y?1:-1,err=dx+dy;while(x!==b.x||y!==b.y){let e=2*err;if(e>=dy){err+=dy;x+=sx}if(e<=dx){err+=dx;y+=sy}if(blocked(x,y))return false}return true}
function covered(e){return [[1,0],[-1,0],[0,1],[0,-1]].some(([dx,dy])=>wall(e.x+dx,e.y+dy))}
function roll(){const n=random(20);$('dice-value').textContent=n;const el=$('dice');el.hidden=true;void el.offsetWidth;el.hidden=false;clearTimeout(diceTimer);diceTimer=setTimeout(()=>el.hidden=true,2300);return n}
function act(label,fn,extra=''){const b=document.createElement('button');b.textContent=label;b.className=extra;b.onclick=fn;$('actions').append(b)}
function select(x,y){if(x<0||x>=W||y<0||y>=H)return;selected={x,y};path=[];if(!blocked(x,y)&&!occupant(x,y)&&visible(x,y))path=route(state.hero,selected)||[];render()}
function move(){if(!path.length||state.complete||state.defeated)return;if(state.combat&&path.length>state.move)return;const p=path[path.length-1],steps=path.length;state.hero.x=p.x;state.hero.y=p.y;if(state.combat)state.move-=steps;else follow();selected=null;path=[];save();render()}
function follow(){for(const ally of state.allies.filter(a=>a.hp>0)){if(dist(ally,state.hero)<=2)continue;const options=[[0,1],[-1,0],[1,0],[0,-1]].map(([dx,dy])=>({x:state.hero.x+dx,y:state.hero.y+dy})).filter(p=>!blocked(p.x,p.y)&&!occupant(p.x,p.y));let best=null;for(const p of options){const r=route(ally,p);if(r&&(!best||r.length<best.length))best=r}if(best&&best.length){const stops=best.slice(0,3).filter(p=>!occupant(p.x,p.y));if(stops.length){const p=stops[stops.length-1];ally.x=p.x;ally.y=p.y}}}}
function openDoor(force){if(dist(state.hero,{x:4,y:5})>1||state.door||state.combat)return;const n=roll(),bonus=force?2:4,dc=force?10:12;if(n+bonus>=dc){state.door=true;state.combat=true;state.move=5;state.acted=false;tell(`d20: ${n} + ${bonus} = ${n+bonus} против ${dc}. Дверь открывается. Два костяных стража оборачиваются к свету. Мира поднимает посох. Начинается бой — ваш ход.`)}else{state.noise=true;tell(`d20: ${n} + ${bonus} = ${n+bonus} против ${dc}. ${force?'Дубовая дверь выдерживает удар.':'Отмычка соскальзывает.'} За дверью звенит металл. Можно попробовать снова или выбить дверь.`)}selected=null;save();render()}
function hit(attacker,target,bonus,sides,flat,cover=false){const n=attacker.id==='hero'?roll():random(20),ac=target.kind==='enemy'?11:12,def=ac+(cover?2:0),success=n===20||(n!==1&&n+bonus>=def);let damage=0;if(success){damage=random(sides)+flat+(n===20?random(sides):0);target.hp=Math.max(0,target.hp-damage)}return `${attacker.name}: d20 ${n} + ${bonus} против ${def}${cover?' (укрытие)':''} — ${success?`${n===20?'критический удар, ':''}${damage} урона по ${target.name}`:'промах'}.`}
function checkBattle(){if(state.hero.hp<=0){state.defeated=true;state.combat=false;tell('Вы падаете на каменные плиты. Экспедиция завершилась поражением. Можно начать новую попытку через меню.');return true}if(state.enemies.every(e=>e.hp<=0)){state.combat=false;state.xp=60;tell('Стражи рассыпаются. В часовне становится тихо. +60 опыта. На северном алтаре лежит реликвия. Заберите её и вернитесь к южному входу.');return true}return false}
function attack(enemy){if(!state.combat||state.acted||enemy.hp<=0||dist(state.hero,enemy)>5||!line(state.hero,enemy))return;const melee=dist(state.hero,enemy)===1;tell(hit(state.hero,enemy,4,melee?8:6,2,!melee&&covered(enemy)));state.acted=true;checkBattle();selected=null;save();render()}
function approach(e,target,steps){for(let i=0;i<steps;i++){if(dist(e,target)<=1)return;let best=null;for(const [dx,dy]of[[0,1],[1,0],[0,-1],[-1,0]]){const p={x:target.x+dx,y:target.y+dy};if(blocked(p.x,p.y)||occupant(p.x,p.y))continue;const r=route(e,p);if(r&&r.length&&(!best||r.length<best.length))best=r}if(!best)return;const step=best.find(p=>!occupant(p.x,p.y));if(!step)return;const cost=best.indexOf(step)+1;if(i+cost>steps)return;e.x=step.x;e.y=step.y;i+=cost-1}}
function endTurn(){if(!state.combat||state.defeated)return;const log=[];for(const ally of state.allies.filter(a=>a.hp>0)){const enemy=state.enemies.filter(e=>e.hp>0).sort((a,b)=>dist(ally,a)-dist(ally,b))[0];if(!enemy)break;if(ally.kind==='mage'&&(dist(ally,enemy)>5||!line(ally,enemy))||ally.kind==='guard'&&dist(ally,enemy)>1)approach(ally,enemy,3);if(dist(ally,enemy)<=(ally.kind==='mage'?5:1)&&line(ally,enemy))log.push(hit(ally,enemy,3,6,1,ally.kind==='mage'&&covered(enemy)));else log.push(`${ally.name} занимает позицию.`)}if(log.length)tell(log.join(' '));if(checkBattle()){save();render();return}log.length=0;for(const e of state.enemies.filter(e=>e.hp>0)){const target=[state.hero,...state.allies].filter(a=>a.hp>0).sort((a,b)=>dist(e,a)-dist(e,b))[0];if(!target)break;approach(e,target,3);if(dist(e,target)<=1)log.push(hit(e,target,2,4,1));else log.push(`${e.name} приближается.`)}if(log.length)tell(log.join(' '));if(!checkBattle()){state.round++;state.move=5;state.acted=false}selected=null;path=[];save();render()}
function interact(type){if(!selected||dist(state.hero,selected)>1||state.combat||state.defeated||state.complete)return;if(type==='chest'){state.chest=true;state.gold+=15;state.potions++;tell('В сундуке сохранились 15 монет и лечебное зелье. На обрывке письма: «Колокол забрали на север. Не верьте настоятелю». Зацепка записана в хронику.')}if(type==='altar'){state.relic=true;tell('Вы поднимаете серебряный язычок исчезнувшего колокола. На металле вырезано имя: «Эллен». Мира узнаёт его, но отводит взгляд. Возвращайтесь к южному входу.')}if(type==='exit'){if(!state.relic){tell('Пока рано уходить: реликвия всё ещё в часовне. Северный проход закрыт дубовой дверью.')}else{state.complete=true;state.xp=100;state.level=2;state.gold+=30;state.hero.max=30;state.hero.hp=30;tell('Вы выходите под утреннее небо. Реликвия найдена. +30 монет, уровень 2. Мира тихо произносит: «Эллен была моей сестрой». Первая глава завершена. Продолжение истории появится в следующей версии.')}}selected=null;save();render()}
function potion(){if(!state.potions||state.hero.hp>=state.hero.max||state.defeated||state.complete||(state.combat&&state.acted))return;const restored=Math.min(10,state.hero.max-state.hero.hp);state.hero.hp+=restored;state.potions--;if(state.combat)state.acted=true;tell(`Вы выпиваете зелье: +${restored} здоровья.${state.combat?' Действие потрачено.':''}`);save();render();inventory()}
function actionPanel(){const box=$('actions');box.replaceChildren();let text='Нажмите на свободную клетку, чтобы проложить путь.';if(state.complete)text='Приключение завершено. Уровень 2 — ваша первая история сохранена.';else if(state.defeated)text='Отряд потерпел поражение. Новая попытка доступна в меню.';else if(selected){const o=object(selected.x,selected.y),e=occupant(selected.x,selected.y),near=dist(state.hero,selected)<=1;if(!visible(selected.x,selected.y)){text='За закрытой дверью. Сначала откройте проход.'}else if(e){text=`${e.name} · ${e.hp}/${e.max} здоровья`;if(e.kind==='enemy'&&state.combat){if(state.acted)text+=' · действие уже потрачено';else if(dist(state.hero,e)>5)text+=' · вне дальности';else if(!line(state.hero,e))text+=' · нет прямой видимости';else act(dist(state.hero,e)===1?'Ударить мечом · d20':'Выстрелить · d20',()=>attack(e))}}else if(o==='door'){text=near?'Дубовая дверь · ловкость 12 или сила 10':'Подойдите к двери вплотную.';if(near&&!state.combat){act('Вскрыть · d20 +4',()=>openDoor(false));act('Выбить · d20 +2',()=>openDoor(true))}}else if(o==='altar'||o==='chest'){text=state.combat?'Сначала завершите бой.':near?(o==='altar'?'Реликвия на алтаре':'Старый дорожный сундук'):'Подойдите к объекту вплотную.';if(near&&!state.combat)act(o==='altar'?'Забрать реликвию':'Открыть сундук',()=>interact(o))}else if(o==='exit'&&near){text='Южный вход в часовню';if(!state.combat)act('Покинуть часовню',()=>interact('exit'))}else if(wall(selected.x,selected.y))text='Каменная кладка · непроходимо';else if(path.length){text=`Маршрут: ${path.length} кл.${state.combat?` · доступно ${state.move}`:''}`;if(!state.combat||path.length<=state.move)act(`Идти · ${path.length} кл.`,move);else text+=' · слишком далеко';}else text='Проход занят или недоступен.'}if(!state.complete&&!state.defeated&&state.combat)act('Завершить ход',endTurn,'secondary');$('selection').textContent=text}
function render(){const ps=[state.hero,...state.allies];$('party').innerHTML=ps.map((p,i)=>`<div class="member ${i===0?'self':''}"><div class="portrait">${['♙','✧','♜'][i]}</div><b>${p.name}${i===0?' · вы':''}</b><small>${p.hp}/${p.max} HP</small><div class="hp-track"><div class="hp-fill" style="width:${p.hp/p.max*100}%"></div></div></div>`).join('');$('phase').textContent=state.complete?'✧ Глава завершена':state.defeated?'◇ Поражение':state.combat?`⚔ Бой · раунд ${state.round}`:'◈ Исследование';$('movement').textContent=state.combat?`Ход: ${state.move} кл. · ${state.acted?'0':'1'} действие`:'Отряд следует за вами';$('quest').textContent=state.complete?'Реликвия спасена. Мира хранит новую тайну.':state.relic?'Вернитесь к южному входу с реликвией.':'Найдите реликвию в заброшенной часовне.';$('level').textContent=`УР. ${state.level}`;$('narrative').textContent=state.narrative;$('journal-count').textContent=state.logs.length;actionPanel();draw()}
const canvas=$('map'),ctx=canvas.getContext('2d');
function draw(){const size=canvas.clientWidth||360,dpr=Math.min(devicePixelRatio||1,3);canvas.width=Math.round(size*dpr);canvas.height=Math.round(size*H/W*dpr);ctx.setTransform(dpr*size/W,0,0,dpr*size/W,0,0);ctx.clearRect(0,0,W,H);ctx.fillStyle='#18201d';ctx.fillRect(0,0,W,H);for(let y=0;y<H;y++)for(let x=0;x<W;x++){const r=((x*73+y*127+state.seed)%17)/17;ctx.fillStyle=wall(x,y)?`rgb(${43+r*12},${49+r*12},${45+r*10})`:`rgb(${78+r*13},${82+r*12},${69+r*10})`;ctx.fillRect(x+.025,y+.025,.95,.95);ctx.strokeStyle=wall(x,y)?'#202820':'#393f33';ctx.lineWidth=.02;ctx.strokeRect(x+.035,y+.035,.93,.93);if(wall(x,y)){ctx.fillStyle='#151c1870';ctx.fillRect(x+.08,y+.7,.9,.25);ctx.strokeStyle='#67715a66';ctx.beginPath();ctx.moveTo(x+.07,y+.1);ctx.lineTo(x+.85,y+.1);ctx.stroke()}else{ctx.strokeStyle='#a09c7930';ctx.beginPath();ctx.moveTo(x+.12,y+.18);ctx.lineTo(x+.4,y+.19);ctx.stroke();if(r>.65){ctx.strokeStyle='#30392b';ctx.beginPath();ctx.moveTo(x+.7,y+.02);ctx.lineTo(x+.6,y+.25);ctx.lineTo(x+.72,y+.36);ctx.stroke()}}}
// A worn runner, benches and scattered leaves remain below the grid and tokens.
ctx.fillStyle='#64574866';ctx.fillRect(3.1,6.1,1.8,3.7);ctx.strokeStyle='#a6976544';ctx.lineWidth=.025;ctx.strokeRect(3.25,6.2,1.5,3.5);for(const y of[6.5,8])for(const x of[1.1,6.2]){ctx.fillStyle='#25291e';ctx.fillRect(x+.05,y+.08,1.3,.35);ctx.fillStyle='#746143';ctx.fillRect(x,y,1.3,.28);ctx.strokeStyle='#a48d5b';ctx.strokeRect(x,y,1.3,.28)}
ctx.fillStyle='#172019';ctx.fillRect(4.1,9.1,.8,.8);ctx.strokeStyle='#c5bb89';ctx.lineWidth=.045;ctx.beginPath();ctx.moveTo(4.3,9.3);ctx.lineTo(4.5,9.6);ctx.lineTo(4.7,9.3);ctx.stroke();
if(!state.door){ctx.fillStyle='#2b2419';ctx.fillRect(4,5,.99,.99);ctx.fillStyle='#8c7047';ctx.fillRect(4.08,5.18,.84,.64);ctx.strokeStyle='#372e22';ctx.lineWidth=.04;for(let i=1;i<4;i++){ctx.beginPath();ctx.moveTo(4.1+i*.19,5.2);ctx.lineTo(4.1+i*.19,5.8);ctx.stroke()}ctx.fillStyle='#dfc78e';ctx.fillRect(4.74,5.45,.08,.12)}else{ctx.fillStyle='#7f6845';ctx.fillRect(4.02,5.03,.13,.88)}
if(!state.chest){ctx.fillStyle='#2b261a';ctx.fillRect(2.1,2.27,.85,.58);ctx.fillStyle='#9a7b48';ctx.fillRect(2.08,2.17,.78,.52);ctx.fillStyle='#d0b87b';ctx.fillRect(2.25,2.17,.08,.52);ctx.fillRect(2.65,2.17,.08,.52);ctx.fillRect(2.44,2.35,.12,.13)}ctx.fillStyle='#252e29';ctx.fillRect(6.05,1.08,.9,.8);ctx.fillStyle='#a29d84';ctx.fillRect(6.1,1.05,.8,.67);if(!state.relic){ctx.shadowColor='#ffe49b';ctx.shadowBlur=.3;ctx.fillStyle='#eedb9e';ctx.beginPath();ctx.ellipse(6.5,1.35,.08,.22,.4,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0}
for(const [x,y]of[[1,4],[7,6]]){const g=ctx.createRadialGradient(x+.5,y+.5,.02,x+.5,y+.5,1.3);g.addColorStop(0,'#dfaf5b45');g.addColorStop(1,'#dfaf5b00');ctx.fillStyle=g;ctx.fillRect(x-.8,y-.8,2.6,2.6);ctx.fillStyle='#d6ac65';ctx.beginPath();ctx.arc(x+.5,y+.5,.07,0,7);ctx.fill()}
if(state.combat&&!state.defeated){ctx.fillStyle='#a6b89312';for(let y=1;y<10;y++)for(let x=1;x<8;x++){if(blocked(x,y)||occupant(x,y))continue;const r=route(state.hero,{x,y});if(r&&r.length<=state.move)ctx.fillRect(x+.05,y+.05,.9,.9)}}
if(path.length){ctx.strokeStyle='#e2d3a3';ctx.lineWidth=.07;ctx.setLineDash([.1,.1]);ctx.beginPath();ctx.moveTo(state.hero.x+.5,state.hero.y+.5);for(const p of path)ctx.lineTo(p.x+.5,p.y+.5);ctx.stroke();ctx.setLineDash([])}
for(const e of [...state.allies,...state.enemies,state.hero])if(e.hp>0)token(e);
if(!state.door){ctx.fillStyle='#101a18e8';ctx.fillRect(0,0,9,5);ctx.fillStyle='#818d7f';ctx.font='.23px sans-serif';ctx.textAlign='center';ctx.fillText('НЕИЗВЕСТНОЕ КРЫЛО',4.5,2.6);ctx.font='.17px sans-serif';ctx.fillText('Откройте дубовую дверь',4.5,2.95)}
if(selected){ctx.strokeStyle='#efd799';ctx.lineWidth=.045;ctx.strokeRect(selected.x+.06,selected.y+.06,.88,.88)}
}
function token(e){const x=e.x+.5,y=e.y+.5,enemy=e.kind==='enemy',color=enemy?'#946250':e.kind==='mage'?'#897293':e.kind==='guard'?'#8297a4':'#9eaa72';ctx.save();ctx.translate(x,y);ctx.fillStyle='#0a120dbb';ctx.beginPath();ctx.ellipse(.07,.17,.38,.25,0,0,7);ctx.fill();ctx.fillStyle='#242d26';ctx.beginPath();ctx.ellipse(0,.05,.35,.3,0,0,7);ctx.fill();ctx.strokeStyle=e.id==='hero'?'#e4c989':enemy?'#b87662':'#a4b6b7';ctx.lineWidth=.035;ctx.stroke();ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(-.2,.2);ctx.quadraticCurveTo(-.3,-.1,-.12,-.24);ctx.lineTo(.13,-.24);ctx.quadraticCurveTo(.26,-.04,.2,.23);ctx.closePath();ctx.fill();ctx.strokeStyle='#1a251e';ctx.lineWidth=.03;ctx.stroke();ctx.fillStyle=enemy?'#d2c9aa':'#cfb697';ctx.beginPath();ctx.arc(0,-.11,.12,0,7);ctx.fill();ctx.fillStyle=enemy?'#4a4234':'#494a36';ctx.beginPath();ctx.arc(0,-.16,.115,Math.PI,Math.PI*2);ctx.fill();ctx.strokeStyle=e.kind==='mage'?'#c0ab76':'#d0d3be';ctx.lineWidth=.045;ctx.beginPath();ctx.moveTo(.21,.16);ctx.lineTo(.28,-.32);ctx.stroke();if(e.kind==='guard'){ctx.fillStyle='#8499a5';ctx.fillRect(-.31,-.04,.15,.25)}if(enemy){ctx.fillStyle='#242b20';ctx.fillRect(-.07,-.13,.04,.035);ctx.fillRect(.03,-.13,.04,.035)}ctx.fillStyle='#212921';ctx.fillRect(-.3,.4,.6,.055);ctx.fillStyle=enemy?'#d38a75':'#a6bc94';ctx.fillRect(-.3,.4,.6*e.hp/e.max,.055);ctx.restore()}
function modal(title,html){$('modal-title').textContent=title;$('modal-content').innerHTML=html;if(!$('modal').open)$('modal').showModal()}
function inventory(){modal('Рюкзак',`<div class="item"><span>Монеты</span><b>${state.gold}</b></div><div class="item"><span>Лечебное зелье · +10 HP</span><b>${state.potions}</b></div><div class="item"><span>Короткий лук · меч</span><span>Экипировано</span></div>${state.relic?'<div class="item"><span>Язычок колокола</span><span>Реликвия</span></div>':''}<p class="hint">В бою зелье расходует действие. Его нельзя выпить при полном здоровье.</p><button id="drink" class="primary">Выпить зелье</button>`);$('drink').disabled=!state.potions||state.hero.hp>=state.hero.max||state.defeated||state.complete||(state.combat&&state.acted);$('drink').onclick=potion}
function character(){modal('Эльдар · следопыт',`<p>Уровень ${state.level} · Опыт ${state.xp}/100 · Здоровье ${state.hero.hp}/${state.hero.max}</p><div class="stat-grid"><div>+2<small>СИЛА</small></div><div>+4<small>ЛОВКОСТЬ</small></div><div>+1<small>МУДРОСТЬ</small></div></div><p>Лук: дальность 5 клеток, d20 +4, урон d6 +2.<br>Меч: соседняя клетка, d20 +4, урон d8 +2.</p><p>Мира — маг, дальность 5 клеток.<br>Бор — защитник, ближний бой.</p><p class="hint">Спутники действуют автоматически после вашего хода по простым правилам. Создание и смена героев появятся позже.</p>`)}
function help(){modal('Как играть',`<ol><li>Нажмите на свободную клетку, затем «Идти». Стены непроходимы. Через союзника можно пройти, но нельзя занять его клетку.</li><li>Подойдите к двери в центре карты вплотную. Нажмите на неё и выберите проверку.</li><li>В бою у вас 5 клеток перемещения и одно действие. Нажмите на врага для атаки.</li><li>«Завершить ход» запускает действия спутников и противников.</li><li>После боя заберите реликвию на северном алтаре. Вернитесь к отмеченному южному выходу.</li></ol><p class="hint">Стены перекрывают выстрел. Противник рядом со стеной получает +2 к защите от дальних атак — упрощённое правило укрытия этой пробы.</p><p class="hint">Броски делает криптографический генератор браузера. Серверная проверка, ИИ-ведущий и совместная игра ещё не подключены. Сохранение привязано к этому браузеру и может исчезнуть при очистке его данных.</p>`)}
$('menu').onclick=()=>{modal('Приключение',`<p>Соло · герой и два спутника</p><p>Тестовая глава «Часовня без колокола». События заданы заранее. Прогресс сохраняется в браузере после действий.</p><div class="button-row"><button class="secondary" id="menu-help">Как играть</button><button class="secondary" id="restart">Новая попытка</button></div>`);$('menu-help').onclick=help;$('restart').onclick=()=>{modal('Начать заново?',`<p>Текущая попытка и её прогресс будут заменены.</p><button class="primary" id="confirm-reset">Начать новую попытку</button>`);$('confirm-reset').onclick=()=>{state=fresh();selected=null;path=[];save();render();$('modal').close()}}};
$('journal').onclick=()=>{modal('Хроника', '<div id="entries"></div>');for(let i=state.logs.length-1;i>=0;i--){const el=document.createElement('div');el.className='journal-entry';const label=document.createElement('small');label.textContent=`СОБЫТИЕ ${i+1}`;el.append(label,document.createTextNode(state.logs[i]));$('entries').append(el)}};
$('custom').onclick=()=>{modal('Своё действие',`<p>ИИ-ведущий пока не подключён. Здесь можно сохранить задумку для сцены — она не изменит игровой мир.</p><textarea id="draft" maxlength="1000" placeholder="Например: отвлекаю стража звоном монеты…" aria-label="Задумка действия"></textarea><div class="button-row"><button class="primary" id="save-draft">Сохранить задумку</button></div>`);$('draft').value=state.draft;$('save-draft').onclick=()=>{state.draft=$('draft').value;save();$('modal').close()}};
$('nav-character').onclick=character;$('nav-inventory').onclick=inventory;$('nav-help').onclick=help;$('nav-map').onclick=()=>canvas.scrollIntoView({behavior:'smooth',block:'center'});$('close-modal').onclick=()=>$('modal').close();$('modal').onclick=e=>{if(e.target===$('modal')){const r=$('modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('modal').close()}};
canvas.addEventListener('click',e=>{const r=canvas.getBoundingClientRect();select(Math.floor((e.clientX-r.left)/r.width*W),Math.floor((e.clientY-r.top)/r.height*H))});canvas.addEventListener('keydown',e=>{const dirs={ArrowUp:[0,-1],ArrowDown:[0,1],ArrowLeft:[-1,0],ArrowRight:[1,0]};if(dirs[e.key]){e.preventDefault();focus.x=Math.max(0,Math.min(8,focus.x+dirs[e.key][0]));focus.y=Math.max(0,Math.min(10,focus.y+dirs[e.key][1]));select(focus.x,focus.y)}if(e.key==='Enter'){$('actions').querySelector('button')?.click()}});
new ResizeObserver(draw).observe(canvas);save();render();
})();
